const buildUsername = (schoolCode, classLevel, studentNumber) => {
  const classInfo = CLASS_LEVELS.find((item) => item.id === classLevel || item.label === classLevel);
  return `${schoolCode}-${classInfo?.shortCode || "B1"}-${String(studentNumber).padStart(3, "0")}`;
};

