const getTemporaryBypassSession = () => {
  const classLevel = getTemporaryBypassClassLevel();
  const student =
    demoStudents.find((item) => item.school_code === "BFA" && item.class_level === classLevel && item.student_number === 1) ||
    demoStudents[0];

  return {
    ...student,
    studentFirstName: student?.student_name || "Adeola",
    studentLastName: "",
    password_changed: true,
    mustChangePassword: false,
    isTemporaryBypass: true,
  };
};

