const getClassInfo = (classLevel) => CLASS_LEVELS.find((item) => item.id === classLevel) || CLASS_LEVELS[0];

const splitTopicSummary = (text) => {
  const [topic, ...summaryParts] = String(text || "").split(":");
  return {
    topic: summaryParts.length ? topic.trim() : text,
    summary: summaryParts.length ? summaryParts.join(":").trim() : "Review, practise and check understanding for this week.",
  };
};

const buildWeekCards = (classLevel) =>
  (firstTermScheme[classLevel] || firstTermScheme["basic-1"]).slice(0, classLevel === "basic-5" ? 14 : ["basic-2", "basic-3", "basic-4", "basic-6"].includes(classLevel) ? 13 : 12).map((entry, index) => ({
    week: index + 1,
    ...splitTopicSummary(entry),
    studyGuide: "Read the teacher notes and worked examples.",
    practiceTest: "Answer a short class-based practice test.",
    mathsGame: "Play the matching maths activity for this topic.",
    quiz: "Complete the quick quiz.",
    progress: index < 2 ? 100 : index === 2 ? 45 : 0,
    badge: index < 2 ? "Earned" : index === 2 ? "In progress" : "Locked",
  }));

