const MOCK_STORAGE_KEY = "pro-tutors-hub-mock-history-v1";


const steps = (...items) => items;

const createMockQuestion = (
  id,
  similarGroup,
  subtopic,
  prompt,
  answer,
  option,
  solution,
  extraAccepted = [],
  meta = {}
) => {
  const lines = prompt.split("\n");
  const stemLines = [];
  const options = [];

  lines.forEach((line) => {
    const match = line.match(/^([A-E])\.\s*(.+)$/);
    if (match) {
      options.push({
        label: match[1],
        text: match[2],
      });
    } else {
      stemLines.push(line);
    }
  });

  return {
    id,
    similarGroup,
    subtopic,
    prompt: stemLines.join("\n"),
    answer,
    options,
    acceptedAnswers: [option, String(option).toLowerCase(), answer, ...extraAccepted],
    solution: steps(...solution),
    ...meta,
  };
};


