const createQuestion = (
  prompt,
  answer,
  solution,
  acceptedAnswers = [],
  solutionDiagram = null,
  questionDiagram = null,
  questionTable = null
) => ({
  prompt,
  answer,
  solution,
  acceptedAnswers: [answer, ...acceptedAnswers],
  solutionDiagram,
  questionDiagram,
  questionTable,
});


const mcqWithQuestionDiagram = (
  prompt,
  answer,
  option,
  solution,
  questionDiagram,
  solutionDiagram = null
) =>
  createQuestion(
    prompt,
    answer,
    solution,
    [option, option.toLowerCase()],
    solutionDiagram,
    questionDiagram
  );

const mcqWithTable = (
  prompt,
  answer,
  option,
  solution,
  questionTable,
  solutionDiagram = null
) =>
  createQuestion(
    prompt,
    answer,
    solution,
    [option, option.toLowerCase()],
    solutionDiagram,
    null,
    questionTable
  );


const mcq = (prompt, answer, option, solution, solutionDiagram = null) =>
  createQuestion(prompt, answer, solution, [option, option.toLowerCase()], solutionDiagram);

