const normalizeAnswer = (value) =>
  String(value || "")
    .normalize("NFKD")
    .replace(/Ã—/g, "x")
    .replace(/Ã·/g, "/")
    .replace(/â‚¦/g, "")
    .replace(/[^a-zA-Z0-9:/.<>=â‰¤â‰¥\-\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();

const NUMBER_WORD_VALUES = {
  zero: 0,
  one: 1,
  two: 2,
  three: 3,
  four: 4,
  five: 5,
  six: 6,
  seven: 7,
  eight: 8,
  nine: 9,
  ten: 10,
  eleven: 11,
  twelve: 12,
  thirteen: 13,
  fourteen: 14,
  fifteen: 15,
  sixteen: 16,
  seventeen: 17,
  eighteen: 18,
  nineteen: 19,
  twenty: 20,
  thirty: 30,
  forty: 40,
  fourty: 40,
  fifty: 50,
  sixty: 60,
  seventy: 70,
  eighty: 80,
  ninety: 90,
};

const SCALE_WORD_VALUES = {
  hundred: 100,
  hundreds: 100,
  thousand: 1000,
  thousands: 1000,
  million: 1000000,
  millions: 1000000,
};

function parseAnswerNumber(value) {
  const normalized = normalizeAnswer(value).replace(/-/g, " ");
  if (!normalized) return null;

  const compactNumber = normalized.replace(/\s+/g, "");
  if (/^-?\d+(\.\d+)?$/.test(compactNumber)) {
    return Number(compactNumber);
  }

  if (!/^[a-z0-9\s-]+$/.test(normalized)) return null;

  const tokens = normalized
    .split(/\s+/)
    .filter(Boolean)
    .filter((token) => token !== "and");

  if (!tokens.length) return null;

  let total = 0;
  let current = 0;
  let sawNumberWord = false;

  for (const token of tokens) {
    if (/^\d+$/.test(token)) {
      current += Number(token);
      sawNumberWord = true;
      continue;
    }

    if (Object.prototype.hasOwnProperty.call(NUMBER_WORD_VALUES, token)) {
      current += NUMBER_WORD_VALUES[token];
      sawNumberWord = true;
      continue;
    }

    if (token === "hundred" || token === "hundreds") {
      if (current === 0) current = 1;
      current *= 100;
      sawNumberWord = true;
      continue;
    }

    if (token === "thousand" || token === "thousands" || token === "million" || token === "millions") {
      const scale = SCALE_WORD_VALUES[token];
      total += (current || 1) * scale;
      current = 0;
      sawNumberWord = true;
      continue;
    }

    return null;
  }

  return sawNumberWord ? total + current : null;
}

function normalizeAnswerWithoutJoiningWords(value) {
  return normalizeAnswer(value)
    .replace(/-/g, " ")
    .split(/\s+/)
    .filter((token) => token && token !== "and")
    .join(" ");
}

function areAnswersEquivalent(expected, response) {
  const normalizedExpected = normalizeAnswer(expected);
  const normalizedResponse = normalizeAnswer(response);
  if (normalizedExpected === normalizedResponse) return true;

  const expectedCompact = normalizedExpected.replace(/\s+/g, "");
  const responseCompact = normalizedResponse.replace(/\s+/g, "");
  if (expectedCompact && expectedCompact === responseCompact) return true;

  if (normalizeAnswerWithoutJoiningWords(expected) === normalizeAnswerWithoutJoiningWords(response)) {
    return true;
  }

  const expectedNumber = parseAnswerNumber(expected);
  const responseNumber = parseAnswerNumber(response);
  return expectedNumber !== null && responseNumber !== null && expectedNumber === responseNumber;
}

const isQuestionCorrect = (question, response) => {
  const normalizedResponse = normalizeAnswer(response);
  if (!normalizedResponse) return false;
  return question.acceptedAnswers.some(
    (item) => areAnswersEquivalent(item, response)
  );
};

