const parseMultipleChoicePrompt = (prompt) => {
  const lines = String(prompt || "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  const optionPattern = /^([A-Z])\.\s+(.+)$/;
  const optionStartIndex = lines.findIndex((line) => optionPattern.test(line));

  if (optionStartIndex <= 0) {
    return null;
  }

  const options = lines.slice(optionStartIndex).map((line) => {
    const match = line.match(optionPattern);
    return match ? { label: match[1], text: match[2] } : null;
  });

  if (options.some((option) => !option)) {
    return null;
  }

  return {
    stem: lines.slice(0, optionStartIndex).join("\n"),
    options,
  };
};

function shuffleArray(items) {
  const clone = [...items];

  for (let index = clone.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [clone[index], clone[swapIndex]] = [clone[swapIndex], clone[index]];
  }

  return clone;
}

function formatTimeLeft(totalSeconds) {
  const safe = Math.max(0, totalSeconds);
  const minutes = Math.floor(safe / 60);
  const seconds = safe % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

function getStoredMockAttempts() {
  if (typeof window === "undefined") return [];

  try {
    const raw = window.localStorage.getItem(MOCK_STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function saveStoredMockAttempt(attempt) {
  if (typeof window === "undefined") return;

  const attempts = getStoredMockAttempts();
  attempts.unshift(attempt);
  window.localStorage.setItem(MOCK_STORAGE_KEY, JSON.stringify(attempts));
}

