function getRemainingAttempts(packId) {
  const pack = getMockConfig(packId);
  if (!pack) return 0;
  if (pack.maxAttempts === null) return "Unlimited";

  const used = getCurrentMonthMockAttempts(pack.packageType, getAttempts()).length;
  return Math.max(pack.maxAttempts - used, 0);
}

function canStartMockPack(packId) {
  const pack = getMockConfig(packId);
  if (!pack) return false;
  return !hasReachedAttemptLimit(pack.packageType, getAttempts());
}

function getGradeFromPercentage(percentage) {
  if (percentage >= 80) return "A";
  if (percentage >= 70) return "B";
  if (percentage >= 60) return "C";
  if (percentage >= 50) return "D";
  return "Needs Practice";
}

function getAnswerExplanation(question) {
  return Array.isArray(question.solution)
    ? question.solution.join(" ")
    : String(question.solution || "");
}

function getOptionAnswerText(question, selectedLabel) {
  if (!selectedLabel) return "";

  const option = question.options?.find((item) => item.label === selectedLabel);
  return option ? `${option.label}. ${option.text}` : selectedLabel;
}

function buildTopicBreakdown(answers) {
  const totals = new Map(
    TOPIC_NAMES.map((topic) => [topic, { topic, correct: 0, total: 0 }])
  );

  answers.forEach((answer) => {
    const topic = answer.topic || "Mixed Word Problems";
    const current = totals.get(topic) || { topic, correct: 0, total: 0 };
    current.correct += answer.isCorrect ? 1 : 0;
    current.total += 1;
    totals.set(topic, current);
  });

  return Array.from(totals.values()).map((entry) => ({
    ...entry,
    percentage: entry.total ? Math.round((entry.correct / entry.total) * 100) : 0,
  }));
}

function getRecentlyUsedQuestionIds(userPackage) {
  return new Set(
    getAttempts()
      .filter((attempt) => attempt.packageType === userPackage)
      .slice(0, 5)
      .flatMap((attempt) => attempt.answers || [])
      .map((answer) => answer.questionId)
  );
}

function shuffleQuestionOptions(question) {
  if (!question.options?.length) return question;

  const shuffledOptions = shuffleArray(question.options).map((option, index) => ({
    ...option,
    label: String.fromCharCode(65 + index),
  }));
  const correctOption = shuffledOptions.find((option) => option.text === question.answer);

  return {
    ...question,
    options: shuffledOptions,
    acceptedAnswers: [
      ...(question.acceptedAnswers || []),
      correctOption?.label,
      correctOption?.label?.toLowerCase(),
    ].filter(Boolean),
  };
}

function pickUniqueMockQuestions(pool, amount, usedGroups, topicLabel, recentlyUsedIds) {
  const shuffled = shuffleArray(pool);
  const preferred = shuffled.filter((question) => !recentlyUsedIds.has(question.id));
  const fallback = shuffled.filter((question) => recentlyUsedIds.has(question.id));
  const weightedPool = [...preferred, ...fallback];
  const picked = [];

  for (const question of weightedPool) {
    const groupKey = question.similarGroup || question.id;

    if (usedGroups.has(groupKey)) continue;

    picked.push(question);
    usedGroups.add(groupKey);

    if (picked.length === amount) break;
  }

  if (picked.length < amount) {
    throw new Error(
      `Not enough unique questions in ${topicLabel}. Needed ${amount}, but only found ${picked.length}. Add more questions with different similarGroup values.`
    );
  }

  return picked;
}

function generateMockExam(packId) {
  const pack = getMockConfig(packId);
  if (!pack) {
    throw new Error("Invalid mock pack selected.");
  }

  const usedGroups = new Set();
  const recentlyUsedIds = getRecentlyUsedQuestionIds(pack.packageType);
  const selectedQuestions = [];

  Object.entries(pack.distribution).forEach(([topicKey, amount]) => {
    const pool = MOCK_QUESTION_BANKS[topicKey] || [];
    const picked = pickUniqueMockQuestions(pool, amount, usedGroups, topicKey, recentlyUsedIds);
    selectedQuestions.push(
      ...picked.map((question) => ({
        ...question,
        topicKey,
        topic: TOPIC_LABELS[topicKey] || topicKey,
      }))
    );
  });

  return shuffleArray(selectedQuestions).map((question, index) => ({
    ...shuffleQuestionOptions(question),
    mockIndex: index + 1,
  }));
}

function generateMockForPackage(userPackage) {
  return generateMockExam(userPackage);
}

function isMockQuestionCorrect(question, userAnswer) {
  return (question.acceptedAnswers || []).some(
    (accepted) => areAnswersEquivalent(accepted, userAnswer)
  );
}



