function Basic2StudyGuideSlidePage({ studentSession, week, onBackToWeek, onBackToWeeks, onNextWeek }) {
  const classInfo = getClassInfo(studentSession?.class_level);
  const activeWeek = week || buildWeekCards(classInfo.id)[0];
  const activeWeekNumber = Number(activeWeek.week);
  const guide = BASIC2_WEEK_GUIDES[activeWeekNumber] || BASIC2_WEEK_GUIDES[1];
  const [slideIndex, setSlideIndex] = useState(() => {
    const localWeekCheck = getLocalBasic2WeekCheck();
    if (localWeekCheck?.week === activeWeekNumber) {
      return Math.min(Math.max(0, localWeekCheck.slideIndex), (BASIC2_WEEK_GUIDES[activeWeekNumber]?.slides?.length || 1) - 1);
    }
    return 0;
  });
  const slide = guide.slides[slideIndex] || guide.slides[0];
  const isFirstSlide = slideIndex === 0;
  const isLastSlide = slideIndex === guide.slides.length - 1;

  const goPrevious = () => setSlideIndex((current) => Math.max(0, current - 1));
  const goNext = () => {
    if (isLastSlide) {
      onNextWeek?.();
      return;
    }
    setSlideIndex((current) => Math.min(guide.slides.length - 1, current + 1));
  };

  return (
    <main className="page-shell basic2-study-shell">
      <Header title={`Basic 2 Week ${activeWeekNumber}: ${guide.title}`} onBack={onBackToWeek} onPrevious={goPrevious} onNext={goNext} />

      <section className="b2-study-layout">
        <section className="b2-board-stage">
          <Basic2DesignedSlide week={activeWeekNumber} slide={slide} slideIndex={slideIndex} guide={guide} />

          <footer className="b2-slide-controls">
            <button type="button" onClick={isFirstSlide ? onBackToWeek : goPrevious}>
              <ArrowLeft size={18} /> {isFirstSlide ? "Back to Week" : "Previous"}
            </button>
            <div>
              {guide.slides.map((item, index) => (
                <button
                  key={`${item.title}-${index}`}
                  className={index === slideIndex ? "active" : ""}
                  type="button"
                  onClick={() => setSlideIndex(index)}
                  aria-label={`Open Basic 2 Week ${activeWeekNumber} screen ${index + 1}`}
                />
              ))}
            </div>
            <button type="button" onClick={goNext}>
              {isLastSlide ? "Next Week" : "Next"} <ArrowRight size={18} />
            </button>
            <button type="button" onClick={onBackToWeeks}><Home size={18} /> Weeks</button>
          </footer>

          <p className="b2-parent-tip"><b>Parent Tip:</b> {guide.parentTip}</p>
        </section>
      </section>
    </main>
  );
}

function getPrimaryWeekLessonData(classId, weekNumber) {
  if (classId === "basic-2" && BASIC2_WEEK_GUIDES[weekNumber]) {
    return BASIC2_WEEK_GUIDES[weekNumber].lessons;
  }
  if (classId === "basic-1" && weekNumber === 1) {
    return BASIC1_WEEK1_LESSONS;
  }
  if (classId === "basic-1" && weekNumber === 3) {
    return BASIC1_WEEK3_LESSONS;
  }
  if (classId === "basic-1" && weekNumber === 4) {
    return BASIC1_WEEK4_LESSONS;
  }
  if (classId === "basic-1" && weekNumber === 5) {
    return BASIC1_WEEK5_LESSONS;
  }
  if (classId === "basic-1" && weekNumber === 6) {
    return BASIC1_WEEK6_LESSONS;
  }
  if (classId === "basic-1" && weekNumber === 8) {
    return BASIC1_WEEK8_LESSONS;
  }
  if (classId === "basic-1" && weekNumber === 9) {
    return BASIC1_WEEK9_LESSONS;
  }
  if (classId === "basic-1" && weekNumber === 10) {
    return BASIC1_WEEK10_LESSONS;
  }

  return buildPrimaryFallbackLessons(classId, weekNumber);
}

function buildPrimaryFallbackLessons(classId, weekNumber) {
  const weeks = buildWeekCards(classId);
  const week = weeks.find((item) => Number(item.week) === Number(weekNumber)) || weeks[0];
  const classInfo = getClassInfo(classId);
  const topic = week?.topic || "Weekly Maths";
  const summary = week?.summary || "Practise the main mathematics skill for this week.";

  return [
    {
      title: topic,
      summary,
      learn: [
        "Read the topic aloud and identify the key maths words.",
        "Look at the examples before trying your own answer.",
        "Check each step slowly before moving to the next activity.",
      ],
      example: `${classInfo.label} Week ${week?.week || weekNumber} focuses on ${topic.toLowerCase()}. Use objects, drawings or number sentences to model each question.`,
      answer: "Show your working, then write the final answer clearly.",
      objects: ["example", "model", "try", "check"],
    },
    {
      title: "Worked Example",
      summary: "Follow one clear example before practising.",
      learn: [
        "Write the question neatly.",
        "Solve one step at a time.",
        "Compare your answer with the question to make sure it makes sense.",
      ],
      example: `Make a simple example for ${topic.toLowerCase()}, solve it with counters, a drawing or a table, then explain the answer in words.`,
      answer: "The correct answer should match the method you used.",
      objects: ["step 1", "step 2", "step 3"],
    },
    {
      title: "Try It",
      summary: "Use this space to practise the same weekly skill.",
      learn: [
        "Create two new questions from the week topic.",
        "Solve both questions in your notebook.",
        "Ask for help if any step is unclear.",
      ],
      example: `Try another question on ${topic.toLowerCase()} and say how you got your answer.`,
      answer: "Submit your attempt after writing your answer.",
      objects: ["question", "answer", "explain"],
    },
  ];
}

function getWeekShortContent(week) {
  if (!week?.summary) return "Open the week to learn and practise.";
  return week.summary.length > 74 ? `${week.summary.slice(0, 74)}...` : week.summary;
}

function getWeekBriefLabel(week) {
  const topic = String(week?.topic || "").trim();
  const summary = String(week?.summary || "").trim();
  const text = `${topic} ${summary}`.toLowerCase();
  const rangeMatch = text.match(/(?:numbers?|counting)\s+(\d+\s*[-–]\s*\d+)/i);
  const upToMatch = text.match(/up to\s+([\d,]+|one million|billions|millions)/i);

  if (text.includes("mid-term")) return "Short break";
  if (text.includes("examination")) return "Exam review";
  if (text.includes("revision")) return "Review practice";
  if (text.includes("resumption")) return "Starter review";
  if (text.includes("roman")) return "Roman symbols";
  if (text.includes("place value")) return "Place value";
  if (text.includes("skip counting")) return "Skip counting";
  if (text.includes("ordering") || text.includes("compare")) return "Compare and order";
  if (text.includes("addition") && text.includes("subtraction")) return "Add and subtract";
  if (text.includes("addition")) return "Adding numbers";
  if (text.includes("subtraction")) return "Taking away";
  if (text.includes("multiplication") && text.includes("division")) return "Multiply and divide";
  if (text.includes("multiplication")) return "Multiplication";
  if (text.includes("division")) return "Division";
  if (text.includes("fraction") && text.includes("decimal") && text.includes("percentage")) return "Fractions and decimals";
  if (text.includes("fraction")) return "Fractions";
  if (text.includes("decimal")) return "Decimals";
  if (text.includes("percentage")) return "Percentages";
  if (text.includes("ratio")) return "Ratios";
  if (text.includes("lcm")) return "LCM practice";
  if (text.includes("hcf")) return "HCF practice";
  if (text.includes("prime")) return "Prime numbers";
  if (text.includes("factor") || text.includes("multiple")) return "Factors and multiples";
  if (text.includes("money")) return "Money problems";
  if (text.includes("measurement")) return "Measurement";
  if (text.includes("scale")) return "Scale drawing";
  if (text.includes("time")) return "Time";
  if (text.includes("shape") || text.includes("geometry")) return "Shapes";
  if (text.includes("data") || text.includes("statistics")) return "Data";
  if (text.includes("probability")) return "Chance";
  if (text.includes("bodmas") || text.includes("order of basic operations")) return "BODMAS";
  if (rangeMatch) return `Numbers ${rangeMatch[1].replace(/\s/g, "")}`;
  if (upToMatch) return `Up to ${upToMatch[1]}`;
  return summary.split(/[.;]/)[0]?.trim().slice(0, 32) || "Learn and practise";
}

function speakWithKidVoice(text, options = {}) {
  if (options.muted || options.isMuted?.()) {
    options.onEnd?.();
    return;
  }
  if (typeof window === "undefined" || !window.speechSynthesis || !text) {
    options.onEnd?.();
    return;
  }

  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  const voices = window.speechSynthesis.getVoices?.() || [];
  utterance.voice =
    voices.find((voice) => /child|kid|junior|zira|samantha|female/i.test(voice.name)) ||
    voices.find((voice) => /english|en-/i.test(`${voice.lang} ${voice.name}`)) ||
    voices[0] ||
    null;
  utterance.rate = 0.82;
  utterance.pitch = 1.32;
  utterance.volume = 1;
  utterance.onstart = () => options.onStart?.();
  utterance.onend = () => options.onEnd?.();
  utterance.onerror = () => options.onEnd?.();
  window.speechSynthesis.speak(utterance);
}

function speakKidVoiceAsync(text, options = {}) {
  return new Promise((resolve) => {
    if (options.muted || options.isMuted?.() || typeof window === "undefined" || !window.speechSynthesis || !text) {
      options.onEnd?.();
      resolve();
      return;
    }

    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices?.() || [];
    utterance.voice =
      voices.find((voice) => /child|kid|junior|zira|samantha|female/i.test(voice.name)) ||
      voices.find((voice) => /english|en-/i.test(`${voice.lang} ${voice.name}`)) ||
      voices[0] ||
      null;
    utterance.rate = options.rate || 0.78;
    utterance.pitch = options.pitch || 1.34;
    utterance.volume = 1;
    utterance.onstart = () => options.onStart?.();
    utterance.onend = () => {
      options.onEnd?.();
      resolve();
    };
    utterance.onerror = () => {
      options.onEnd?.();
      resolve();
    };
    window.speechSynthesis.speak(utterance);
  });
}

function getSpeechRecognition() {
  if (typeof window === "undefined") return null;
  return window.SpeechRecognition || window.webkitSpeechRecognition || null;
}

async function requestMicrophoneAccess() {
  if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
    return { ok: false, reason: "unsupported" };
  }

  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    stream.getTracks().forEach((track) => track.stop());
    return { ok: true };
  } catch (error) {
    return { ok: false, reason: error?.name || "denied" };
  }
}

function detectSpokenNumber(transcript) {
  const clean = String(transcript || "").toLowerCase();
  const wordMap = {
    one: 1,
    won: 1,
    two: 2,
    too: 2,
    to: 2,
    three: 3,
    tree: 3,
    four: 4,
    for: 4,
    five: 5,
    six: 6,
    seven: 7,
    eight: 8,
    ate: 8,
    nine: 9,
    ten: 10,
  };
  const digitMatch = clean.match(/\b(10|[1-9])\b/);
  if (digitMatch) return Number(digitMatch[1]);
  const foundWord = Object.keys(wordMap).find((word) => new RegExp(`\\b${word}\\b`).test(clean));
  return foundWord ? wordMap[foundWord] : null;
}

function waitMs(duration) {
  return new Promise((resolve) => window.setTimeout(resolve, duration));
}

