function PlusIconFallback({ size = 32 }) {
  return (
    <span className="b1-symbol-icon" style={{ fontSize: size }}>
      +=
    </span>
  );
}

function MinusIconFallback({ size = 32 }) {
  return (
    <span className="b1-symbol-icon" style={{ fontSize: size }}>
      -
    </span>
  );
}

function getWeekTopicVisual(week) {
  const topic = String(week?.topic || "Weekly Maths").trim();
  const summary = String(week?.summary || "").trim();
  const text = `${topic} ${summary}`.toLowerCase();
  let Icon = BookOpen;

  if (text.includes("mid-term") || text.includes("revision") || text.includes("examination") || text.includes("test")) {
    Icon = Star;
  } else if (text.includes("addition") && !text.includes("subtraction")) {
    Icon = PlusIconFallback;
  } else if (text.includes("subtraction") && !text.includes("addition")) {
    Icon = MinusIconFallback;
  } else if (text.includes("multiplication") || text.includes("division") || text.includes("bodmas") || text.includes("operation")) {
    Icon = Calculator;
  } else if (text.includes("fraction") || text.includes("decimal") || text.includes("percentage") || text.includes("ratio")) {
    Icon = PieChart;
  } else if (text.includes("roman")) {
    Icon = BookMarked;
  } else if (text.includes("place value") || text.includes("whole number") || text.includes("counting") || text.includes("ordering") || text.includes("compare")) {
    Icon = Calculator;
  } else if (text.includes("shape") || text.includes("geometry") || text.includes("angle")) {
    Icon = Shapes;
  } else if (text.includes("measure") || text.includes("scale") || text.includes("time") || text.includes("length") || text.includes("area") || text.includes("volume")) {
    Icon = LineChart;
  } else if (text.includes("money") || text.includes("profit") || text.includes("loss") || text.includes("interest")) {
    Icon = Coins;
  } else if (text.includes("lcm") || text.includes("hcf") || text.includes("factor") || text.includes("multiple") || text.includes("prime")) {
    Icon = BarChart3;
  } else if (text.includes("data") || text.includes("statistics") || text.includes("probability") || text.includes("chart")) {
    Icon = ChartNoAxesCombined;
  } else if (text.includes("problem") || text.includes("reasoning")) {
    Icon = HelpCircle;
  }

  return {
    title: topic,
    subtitle: getWeekBriefLabel(week),
    Icon,
  };
}

