function Basic4MissionNode({ week, status, onOpen }) {
  const { title, subtitle } = getWeekTopicVisual(week);
  const symbol = BASIC4_MISSION_SYMBOLS[week.week - 1] || week.week;
  return (
    <button className={`b4-mission week-${week.week} ${status}`} type="button" onClick={onOpen}>
      <span className="b4-week-badge">{week.week}</span>
      <span className="b4-pedestal">
        <img src={`${BASIC4_ASSET_BASE}/basic4-mission-pedestal.png`} alt="" />
        <b>{symbol}</b>
      </span>
      <strong>{title}</strong>
      <small>{subtitle}</small>
      <em aria-hidden="true">{status === "locked" ? <LockKeyhole size={14} /> : <CheckCircle2 size={16} />}</em>
    </button>
  );
}

