function normalizeAnswerText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .replace(/\s*([,+;=<>-])\s*/g, "$1")
    .trim();
}

function Basic3StudyFigure({ figure }) {
  if (!figure) return null;

  const renderTableCell = (cell) => {
    if (Array.isArray(cell)) {
      return (
        <span className="b3-cell-parts">
          {cell.map((part, index) => {
            const partConfig = typeof part === "string" ? { text: part } : part;
            return (
              <span
                className={partConfig.circle ? "b3-circled-value" : ""}
                key={`${partConfig.text}-${index}`}
              >
                {partConfig.text}
              </span>
            );
          })}
        </span>
      );
    }

    if (cell && typeof cell === "object") {
      return <span className={cell.circle ? "b3-circled-value" : ""}>{cell.text}</span>;
    }

    return cell;
  };

  if (figure.type === "table") {
    return (
      <div className="b3-table-wrap">
        <table className="b3-table">
          {Array.isArray(figure.headerRows) ? (
            <thead>
              {figure.headerRows.map((headerRow, rowIndex) => (
                <tr key={`header-row-${rowIndex}`}>
                  {headerRow.map((header, headerIndex) => {
                    const headerConfig = typeof header === "string" ? { label: header } : header;
                    return (
                      <th
                        key={`${headerConfig.label}-${headerIndex}`}
                        colSpan={headerConfig.colSpan || 1}
                        rowSpan={headerConfig.rowSpan || 1}
                      >
                        {headerConfig.label}
                      </th>
                    );
                  })}
                </tr>
              ))}
            </thead>
          ) : Array.isArray(figure.headers) && (
            <thead>
              <tr>{figure.headers.map((header) => <th key={header}>{header}</th>)}</tr>
            </thead>
          )}
          <tbody>
            {figure.rows.map((row, rowIndex) => (
              <tr key={`${rowIndex}-${row.map((cell) => Array.isArray(cell) ? cell.map((part) => part.text || part).join("") : cell.text || cell).join("-")}`}>
                {row.map((cell, cellIndex) => <td key={`${cellIndex}-${Array.isArray(cell) ? cellIndex : cell.text || cell}`}>{renderTableCell(cell)}</td>)}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  if (figure.type === "numberGrid") {
    return (
      <div className="b3-number-grid">
        {figure.values.map((value) => <span key={value}>{value}</span>)}
      </div>
    );
  }

  if (figure.type === "numberLine") {
    return (
      <div className="b3-number-line">
        {figure.values.map((value) => <span key={value}>{value}</span>)}
      </div>
    );
  }

  if (figure.type === "placeValue") {
    return (
      <div className="b3-table-wrap">
        <table className="b3-table">
          <thead><tr><th>Number</th><th>Hundreds</th><th>Tens</th><th>Units</th><th>Expanded form</th></tr></thead>
          <tbody>
            {figure.rows.map((row) => (
              <tr key={row.join("-")}>{row.map((cell) => <td key={cell}>{renderTableCell(cell)}</td>)}</tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  if (figure.type === "comparison" || figure.type === "fractionCompare") {
    const renderExpression = (parts) => (
      <span key={parts.join("-")}>
        {parts.map((part, index) =>
          ["+", "-", "=", "<", ">"].includes(String(part).trim()) ? (
            <strong key={`${part}-${index}`}>{part}</strong>
          ) : (
            <b key={`${part}-${index}`}>{part}</b>
          )
        )}
      </span>
    );

    return (
      <div className="b3-comparison-row">
        {figure.pairs?.map(([left, sign, right]) => (
          <span key={`${left}-${sign}-${right}`}><b>{left}</b><strong>{sign}</strong><b>{right}</b></span>
        ))}
        {figure.rows?.map(renderExpression)}
      </div>
    );
  }

  if (figure.type === "fraction") {
    return (
      <div className="b3-fraction-model" style={{ "--parts": figure.denominator }}>
        {Array.from({ length: figure.denominator }, (_, index) => (
          <span className={index < figure.numerator ? "shaded" : ""} key={index} />
        ))}
        <b>{figure.numerator}/{figure.denominator}</b>
      </div>
    );
  }

  if (figure.type === "counters") {
    return (
      <div className="b3-counter-model">
        {Array.from({ length: figure.total }, (_, index) => (
          <span className={`group-${index % figure.groups}`} key={index} />
        ))}
      </div>
    );
  }

  if (figure.type === "column") {
    return (
      <div className="b3-column-card">
        <span>{figure.top}</span>
        <span><b>{figure.sign}</b>{figure.bottom}</span>
        <strong>{figure.answer}</strong>
      </div>
    );
  }

  if (figure.type === "partial") {
    return (
      <div className="b3-table-wrap">
        <table className="b3-table compact">
          <tbody>
            {figure.rows.map((row) => (
              <tr key={row.join("-")}>{row.map((cell) => <td key={cell}>{cell}</td>)}</tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  if (figure.type === "checklist") {
    return (
      <div className="b3-checklist">
        {figure.items.map((item) => <span key={item}><CheckCircle2 size={16} /> {item}</span>)}
      </div>
    );
  }

  return null;
}

function Basic3DocumentNotesPanel({ week, notesData = BASIC3_DOCUMENT_NOTES }) {
  const notes = notesData.weeks[week.week] || [];
  return (
    <section className="b3-document-panel">
      <div className="b3-document-heading">
        <div>
          <h2>Full Lesson Notes</h2>
        </div>
        <BookMarked size={34} />
      </div>

      {week.week === 1 && (
        <>
          <article className="b3-doc-block intro">
            <h3>How To Learn</h3>
            {notesData.intro.map((item) => <p key={item}>{item}</p>)}
          </article>
          <article className="b3-doc-block intro">
            <h3>Useful App Interactions</h3>
            <ul>{notesData.interactions.map((item) => <li key={item}>{item}</li>)}</ul>
          </article>
        </>
      )}

      <div className="b3-doc-flow">
        {notes.map((section) => (
          <article className={`b3-doc-block ${String(section.heading).toLowerCase().includes("answer") ? "answers" : ""}`} key={section.heading}>
            <h3>{section.heading}</h3>
            {section.body && <p>{section.body}</p>}
            {section.list && (
              <ol>
                {section.list.map((item) => <li key={item}>{item}</li>)}
              </ol>
            )}
          </article>
        ))}
      </div>

    </section>
  );
}

