function getBasic3StudySteps(topic) {
  if (Array.isArray(topic.steps) && topic.steps.length > 0) return topic.steps;
  if (BASIC3_TOPIC_BREAKDOWNS[topic.title]) return BASIC3_TOPIC_BREAKDOWNS[topic.title];
  return String(topic.explanation || "")
    .split(/(?<=[.!?])\s+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function Basic3MiniFractionCircle({ label, numerator, denominator }) {
  const shadedDegrees = Math.max(0, Math.min(360, (Number(numerator) / Number(denominator)) * 360));
  return (
    <figure className="b3-mini-fraction">
      <div
        className={`b3-mini-fraction-circle parts-${denominator}`}
        style={{ "--shaded-degrees": `${shadedDegrees}deg` }}
      />
      <figcaption>{label}</figcaption>
    </figure>
  );
}

function Basic3StepVisual({ topicTitle, step }) {
  const text = String(step || "");

  if (topicTitle === "Equivalent and Ordered Fractions" && text.includes("1/2 and shading 2/4")) {
    return (
      <div className="b3-step-visual equivalent-bars" aria-label="Visual model showing one-half equals two-quarters">
        <Basic3MiniFractionCircle label="1/2 shaded" numerator={1} denominator={2} />
        <strong>=</strong>
        <Basic3MiniFractionCircle label="2/4 shaded" numerator={2} denominator={4} />
      </div>
    );
  }

  if (topicTitle === "Equivalent and Ordered Fractions" && text.includes("5/8 is greater than 3/8")) {
    return (
      <div className="b3-step-visual equivalent-bars" aria-label="Visual model comparing three-eighths and five-eighths">
        <Basic3MiniFractionCircle label="3/8" numerator={3} denominator={8} />
        <strong>&lt;</strong>
        <Basic3MiniFractionCircle label="5/8" numerator={5} denominator={8} />
      </div>
    );
  }

  if (topicTitle === "Adding Like Fractions" && (text.includes("2 seventh-pieces") || text.includes("Write the answer as 5/7"))) {
    return (
      <div className="b3-step-visual addition-bars" aria-label="Visual model showing two sevenths plus three sevenths equals five sevenths">
        <Basic3MiniFractionCircle label="2/7" numerator={2} denominator={7} />
        <strong>+</strong>
        <Basic3MiniFractionCircle label="3/7" numerator={3} denominator={7} />
        <strong>=</strong>
        <Basic3MiniFractionCircle label="5/7" numerator={5} denominator={7} />
      </div>
    );
  }

  return null;
}

function Basic3TopicCard({ weekNumber, topic, topicIndex, colour, classKey = "basic3" }) {
  const storageKey = `proTutorsHub_${classKey}_week${weekNumber}_topic${topicIndex}_answers`;
  const [isOpen, setIsOpen] = useState(topicIndex === 0);
  const [practiceState, setPracticeState] = useState(() => {
    if (typeof window === "undefined") return {};
    try {
      const saved = JSON.parse(window.localStorage.getItem(storageKey) || "{}");
      return saved.answers ? saved : { answers: saved, submitted: {}, revealed: {} };
    } catch {
      return {};
    }
  });
  const answers = practiceState.answers || {};
  const submitted = practiceState.submitted || {};
  const revealed = practiceState.revealed || {};
  const studySteps = getBasic3StudySteps(topic);

  const savePracticeState = (nextState) => {
    setPracticeState(nextState);
    if (typeof window !== "undefined") {
      window.localStorage.setItem(storageKey, JSON.stringify(nextState));
    }
  };

  const updateAnswer = (index, value) => {
    savePracticeState({
      answers: { ...answers, [index]: value },
      submitted: { ...submitted, [index]: false },
      revealed: { ...revealed, [index]: false },
    });
  };

  const submitAnswer = (index) => {
    savePracticeState({
      answers,
      submitted: { ...submitted, [index]: true },
      revealed,
    });
  };

  const revealAnswer = (index) => {
    savePracticeState({
      answers,
      submitted: { ...submitted, [index]: true },
      revealed: { ...revealed, [index]: true },
    });
  };

  return (
    <article className={`b3-topic-card ${isOpen ? "open" : ""}`} style={{ "--topic-colour": colour }}>
      <button className="b3-topic-toggle" type="button" onClick={() => setIsOpen((value) => !value)} aria-expanded={isOpen}>
        <span>{topicIndex + 1}</span>
        <div>
          <strong>{topic.title}</strong>
          <small>{topic.summary}</small>
        </div>
        <b>{isOpen ? "Close" : "Open"}</b>
      </button>

      {isOpen && (
        <div className="b3-topic-body">
          <p>{topic.explanation}</p>
          {studySteps.length > 0 && (
            <ol className="b3-study-steps">
              {studySteps.map((step, stepIndex) => (
                <li key={step}>
                  <span>{stepIndex + 1}</span>
                  <div>
                    <p>{step}</p>
                    <Basic3StepVisual topicTitle={topic.title} step={step} />
                  </div>
                </li>
              ))}
            </ol>
          )}
          <div className="b3-tip"><Sparkles size={18} /> {topic.tip}</div>
          <Basic3StudyFigure figure={topic.figure} />

          {Array.isArray(topic.workedExamples) && topic.workedExamples.length > 0 && (
            <section className="b3-worked-examples">
              <h3>More Examples</h3>
              {topic.workedExamples.map((example) => (
                <article key={example.title}>
                  <strong>{example.title}</strong>
                  <ol>
                    {example.steps.map((step) => <li key={step}>{step}</li>)}
                  </ol>
                </article>
              ))}
            </section>
          )}

          <section className="b3-task-panel">
            <div className="b3-task-heading">
              <h3>To Do</h3>
              <p>Type your answer, then submit each one to check it.</p>
            </div>
            {topic.tasks.map((task, index) => {
              const typed = answers[index] || "";
              const hasSubmitted = Boolean(submitted[index]);
              const isCorrect = hasSubmitted && normalizeAnswerText(typed) === normalizeAnswerText(task.answer);
              return (
                <label className={`b3-answer-row ${isCorrect ? "correct" : ""}`} key={task.prompt}>
                  <span>{task.prompt}</span>
                  <textarea
                    value={typed}
                    onChange={(event) => updateAnswer(index, event.target.value)}
                    placeholder="Type your answer here"
                    rows={2}
                  />
                  <div className="b3-answer-actions">
                    <button type="button" onClick={() => submitAnswer(index)} disabled={!String(typed).trim()}>
                      Submit
                    </button>
                    {hasSubmitted && !isCorrect && (
                      <button type="button" className="secondary" onClick={() => revealAnswer(index)}>
                        Show Answer
                      </button>
                    )}
                  </div>
                  {hasSubmitted && (
                    <small className={isCorrect ? "right" : "wrong"}>
                      {isCorrect ? "Correct. Well done." : "Not yet. Check your method and try again."}
                    </small>
                  )}
                  {revealed[index] && <small>Answer: {task.answer}</small>}
                </label>
              );
            })}
          </section>
        </div>
      )}
    </article>
  );
}

function BasicStudyGuidePage({
  studentSession,
  week,
  onBack,
  onBackToWeeks,
  weeks,
  notesData,
  classLabel,
  classKey,
}) {
  const initialWeekNumber = Number(week?.week || 0);
  const launchedFromWeek = Boolean(initialWeekNumber);
  const [selectedWeekNumber, setSelectedWeekNumber] = useState(initialWeekNumber || weeks[0]?.week || null);
  const selectedWeek = weeks.find((item) => item.week === selectedWeekNumber);

  useEffect(() => {
    setSelectedWeekNumber(Number(week?.week || 0) || weeks[0]?.week || null);
  }, [week?.week, weeks]);

  if (!selectedWeek) {
    if (launchedFromWeek) {
      return (
        <main className="page-shell b3-study-shell">
          <Header title={`${classLabel} Study Guide`} onBack={onBackToWeeks || onBack} onPrevious={onBack} onNext={onBackToWeeks} />
          <section className="b3-study-hero">
            <div>
              <span>{classLabel} Mathematics - First Term</span>
              <h1>Week Study Guide</h1>
              <p>This week's study guide is not available yet.</p>
            </div>
            <BookOpen size={74} />
          </section>
        </main>
      );
    }

    return (
      <main className="page-shell b3-study-shell">
        <Header title={`${classLabel} Study Guide`} onBack={onBack} onPrevious={onBack} onNext={onBackToWeeks} />
        <section className="b3-study-hero">
          <div>
            <span>{classLabel} Mathematics - First Term</span>
            <h1>Study Guide</h1>
            <p>Choose a week to open the full study guide. Each week has colourful topic cards, examples, visual models, tips and answer spaces.</p>
          </div>
          <BookOpen size={74} />
        </section>
        <section className="b3-week-grid">
          {weeks.map((item) => (
            <button
              className="b3-week-card"
              type="button"
              key={item.week}
              style={{ "--week-colour": item.colour }}
              onClick={() => setSelectedWeekNumber(item.week)}
            >
              <span>Week {item.week}</span>
              <strong>{item.title}</strong>
              <small>{item.goal}</small>
              <b>Open Study Guide <ArrowRight size={16} /></b>
            </button>
          ))}
        </section>
      </main>
    );
  }

  return (
    <main className="page-shell b3-study-shell">
      <Header
        title={`Week ${selectedWeek.week} Study Guide`}
        onBack={launchedFromWeek ? (onBackToWeeks || onBack) : onBack}
        onPrevious={selectedWeek.week > 1 ? () => setSelectedWeekNumber(selectedWeek.week - 1) : undefined}
        onNext={selectedWeek.week < weeks.length ? () => setSelectedWeekNumber(selectedWeek.week + 1) : undefined}
      />

      <section className="b3-week-detail-hero" style={{ "--week-colour": selectedWeek.colour }}>
        <button
          className="week-back-button"
          type="button"
          onClick={launchedFromWeek ? (onBackToWeeks || onBack) : onBack}
          aria-label={launchedFromWeek ? `Back to week ${selectedWeek.week}` : `Back to ${classLabel} study weeks`}
        >
          <ArrowLeft size={22} />
        </button>
        <div>
          <span>{studentSession?.student_name || classLabel} - First Term</span>
          <h1>Week {selectedWeek.week}: {selectedWeek.title}</h1>
          <p>{selectedWeek.goal}</p>
        </div>
        <Target size={58} />
      </section>

      <Basic3DocumentNotesPanel week={selectedWeek} notesData={notesData} />

      <section className="b3-topic-list">
        {selectedWeek.topics.map((topic, index) => (
          <Basic3TopicCard
            key={topic.title}
            weekNumber={selectedWeek.week}
            topic={topic}
            topicIndex={index}
            colour={selectedWeek.colour}
            classKey={classKey}
          />
        ))}
      </section>

      <div className="primary-week-nav">
        <button disabled={selectedWeek.week <= 1} onClick={() => setSelectedWeekNumber(selectedWeek.week - 1)}>Previous Week</button>
        <button onClick={launchedFromWeek ? (onBackToWeeks || onBack) : onBack}>
          {launchedFromWeek ? "Back to Week" : "Back to Weeks"}
        </button>
        <button disabled={selectedWeek.week >= weeks.length} onClick={() => setSelectedWeekNumber(selectedWeek.week + 1)}>Next Week</button>
      </div>
    </main>
  );
}

