function PrimaryActivityPage({ studentSession, week, activity, onBack, onBackToWeeks, onOpenGames }) {
  const classInfo = getClassInfo(studentSession?.class_level);
  const weeks = buildWeekCards(classInfo.id);
  const totalWeeks = weeks.length;
  const activeWeek = week || weeks[0];
  const activeWeekNumber = Number(activeWeek.week);
  const activityTitle = activity?.title || "Activity";
  const lessonData = getPrimaryWeekLessonData(classInfo.id, activeWeek.week);
  const isStudyGuide = activity?.id === "studyGuide";
  const hasPrimaryStudyGuide =
    isStudyGuide &&
    ["basic-1", "basic-2"].includes(classInfo.id) &&
    lessonData.length > 0 &&
    lessonData[0]?.title !== "Study Guide";
  const activityCopy = {
    "Study Guide": "This class study guide area is empty for now. The content you supply will appear here.",
    Practice: "Practice questions for this class and week will appear here after we add them.",
    "Quick Quiz": "Quick quiz questions for this week will appear here after we add them.",
    Rewards: "Rewards for this class will be connected here without showing Common Entrance content.",
    "Week Challenge": "Weekly challenge content will be added here for this class.",
  };
  const isGame = activity?.id === "games";

  if (isStudyGuide && classInfo.id === "basic-3") {
    return (
      <Basic3StudyGuidePage
        studentSession={studentSession}
        week={week}
        onBack={onBack}
        onBackToWeeks={onBackToWeeks}
      />
    );
  }

  if (isStudyGuide && classInfo.id === "basic-4") {
    return (
      <Basic4StudyGuidePage
        studentSession={studentSession}
        week={week}
        onBack={onBack}
        onBackToWeeks={onBackToWeeks}
      />
    );
  }

  if (isStudyGuide && classInfo.id === "basic-5") {
    return (
      <Basic5StudyGuidePage
        studentSession={studentSession}
        week={week}
        onBack={onBack}
        onBackToWeeks={onBackToWeeks}
      />
    );
  }

  if (isStudyGuide && classInfo.id === "basic-6") {
    return (
      <Basic6StudyGuidePage
        studentSession={studentSession}
        week={week}
        onBack={onBack}
        onBackToWeeks={onBackToWeeks}
      />
    );
  }

  if (hasPrimaryStudyGuide) {
    const basic2Guide = classInfo.id === "basic-2" ? BASIC2_WEEK_GUIDES[activeWeekNumber] : null;
    const guideNumbers = basic2Guide?.slides?.find((item) => item.type === "chart")?.numbers ||
      (activeWeekNumber === 3
      ? Array.from({ length: 20 }, (_, index) => index + 1)
      : activeWeekNumber === 4
        ? Array.from({ length: 10 }, (_, index) => index + 21)
      : activeWeekNumber === 5
        ? Array.from({ length: 10 }, (_, index) => index + 31)
      : activeWeekNumber === 6
        ? Array.from({ length: 10 }, (_, index) => index + 41)
      : activeWeekNumber === 8
        ? Array.from({ length: 40 }, (_, index) => index + 61)
      : activeWeekNumber === 9
        ? Array.from({ length: 10 }, (_, index) => index + 51)
      : activeWeekNumber === 10
        ? Array.from({ length: 20 }, (_, index) => index + 1)
      : Array.from({ length: 10 }, (_, index) => index + 1));
    const everydayExamples = basic2Guide
      ? basic2Guide.focus
      : activeWeekNumber === 3
      ? "Numbers 1 to 20 help us count bigger groups. We can count pupils in a line, books on a shelf, blocks on a table and steps from one place to another."
      : activeWeekNumber === 4
        ? "Numbers 21 to 30 help us count larger groups. Number names help us write small numbers in words, like 4 as four and 10 as ten."
      : activeWeekNumber === 5
        ? "Numbers 31 to 40 help us count larger groups. Zero helps us show that there is nothing or none in a group."
      : activeWeekNumber === 6
        ? "Numbers 41 to 50 help us count bigger groups. We can compare two groups using more, less and same, then arrange numbers from smallest to biggest or biggest to smallest."
      : activeWeekNumber === 8
        ? "Numbers 61 to 100 help us count much larger groups. Counting in tens helps us count faster, and quantitative reasoning helps us think carefully about missing, bigger and smaller numbers."
      : activeWeekNumber === 9
        ? "Addition helps us put two groups together to find how many there are in all. We can add with pencils, balls, tally marks, bottle tops, fingers and stories."
      : activeWeekNumber === 10
        ? "Addition within 20 means the answer is not more than 20. We can count on, jump on a number line, write addition across, or write it up and down."
      : "Numbers help us count things around us. We can count books, pencils, toys, fruits, chairs and people.";
    const practicePrompt = basic2Guide
      ? `Try this: ${basic2Guide.slides?.find((item) => item.type === "quiz")?.questions?.[0] || lessonData[0]?.example || "read the examples and write your answer."}`
      : activeWeekNumber === 3
      ? "Try this: count 1 to 20, count backwards from 20 to 1, then arrange 4, 2, 1, 3 from smallest to biggest."
      : activeWeekNumber === 4
        ? "Try this: count 21 to 30, count backwards from 30 to 21, then read one, two, three, four, five, six, seven, eight, nine and ten."
      : activeWeekNumber === 5
        ? "Try this: count 31 to 40, count backwards from 40 to 31, then say: 0 is zero, O is a letter."
      : activeWeekNumber === 6
        ? "Try this: count 41 to 50, count backwards from 50 to 41, then arrange 34, 22, 29 and 40 from smallest to biggest."
      : activeWeekNumber === 8
        ? "Try this: count 61 to 100, count in tens from 10 to 100, then find the missing number in 61, 62, 63, __."
      : activeWeekNumber === 9
        ? "Try this: put 3 bottle tops and 2 bottle tops together. Count all the bottle tops to find 3 + 2 = 5."
      : activeWeekNumber === 10
        ? "Try this: start at 8 and count 2 more. Say 9, 10. So, 8 + 2 = 10."
      : "Try this: count 1 to 10 with your fingers, then count 10 to 1 slowly.";
    return (
      <main className="page-shell primary-week-page">
        <Header title={`${classInfo.label} Study Guide`} onBack={onBack} onPrevious={onBack} onNext={onBackToWeeks} />

        <section className="week-detail-shell">
          <div className="week-detail-heading">
            <button className="week-back-button" onClick={onBack} aria-label="Back">
              <ArrowLeft size={22} />
            </button>
            <div>
              <h1>Study Guide: Week {activeWeek.week} {activeWeek.topic}</h1>
              <p>{classInfo.label} &gt; First Term &gt; Week {activeWeek.week} of {weeks.length}</p>
            </div>
          </div>

          <section className="study-guide-page-grid">
            {lessonData.map((lesson, index) => (
              <article className="study-guide-section-card" key={lesson.title}>
                <span>{index + 1}</span>
                <h2>{lesson.title}</h2>
                <p>{lesson.summary}</p>
                <div className="study-guide-object-row">
                  {lesson.objects.map((item) => <b key={item}>{item}</b>)}
                </div>
              </article>
            ))}
          </section>

          <section className="study-guide-rich full">
            <h3>Everyday Number Examples</h3>
            <p>{everydayExamples}</p>
            <p>{practicePrompt}</p>
            <div className="number-strip">
              {guideNumbers.map((number) => <span key={number}>{number}</span>)}
            </div>
          </section>

          <div className="primary-week-nav">
            <button onClick={onBack}>Back</button>
            <button onClick={onBackToWeeks}>Back to Week</button>
            <button onClick={onBackToWeeks}>Continue</button>
          </div>
        </section>
      </main>
    );
  }

  return (
    <main className="page-shell primary-week-page">
      <Header title={`${classInfo.label} ${activityTitle}`} onBack={onBack} onPrevious={onBack} onNext={isGame ? onOpenGames : onBackToWeeks} />

      <section className="primary-week-hero">
        <div className="primary-week-tabs">
          <span>{classInfo.label}</span>
          <strong>First Term</strong>
            <span>Week {activeWeek.week} of {totalWeeks}</span>
        </div>

        <div className="primary-week-heading">
          <div>
            <h1>{activityTitle}</h1>
            <p>{activityCopy[activityTitle] || "This primary-class activity page is ready for your content."}</p>
          </div>
          <div className="primary-class-mascot" aria-hidden="true">
            <Sparkles size={52} />
          </div>
        </div>

        <section className="primary-empty-content">
          <BookMarked size={42} />
          <h2>No Basic 1-4 content added yet</h2>
          <p>
            The old Common Entrance information has been removed from this path. We will add the correct class study guide,
            practice questions, quizzes and activities gradually as you provide them.
          </p>
        </section>

        <div className="primary-week-nav">
          <button onClick={onBack}>Back</button>
          <button onClick={onBackToWeeks}>Back to Weeks</button>
          <button onClick={isGame ? onOpenGames : onBackToWeeks}>{isGame ? "Open Maths Games" : "Continue Later"}</button>
        </div>
      </section>
    </main>
  );
}

