function StudyGuideLessonPage({ topic, lesson, onBack, onPrevious, onNext }) {
  const content = topicContent[topic?.id]?.[lesson];
  const Icon = topic?.icon || BookOpen;
  const requiredStudySeconds = 300;
  const lessonKey = topic?.title && lesson ? `${topic.title}::${lesson}` : "";
  const [isStudied, setIsStudied] = useState(() =>
    Boolean(lessonKey && getStudyGuideProgress().studiedLessons.includes(lessonKey))
  );
  const [secondsOnPage, setSecondsOnPage] = useState(0);
  const canMarkStudied = secondsOnPage >= requiredStudySeconds || isStudied;

  useEffect(() => {
    setIsStudied(Boolean(lessonKey && getStudyGuideProgress().studiedLessons.includes(lessonKey)));
    setSecondsOnPage(0);
  }, [lessonKey]);

  useEffect(() => {
    if (isStudied) return undefined;

    const timer = window.setInterval(() => {
      setSecondsOnPage((currentSeconds) => Math.min(requiredStudySeconds, currentSeconds + 1));
    }, 1000);

    return () => window.clearInterval(timer);
  }, [isStudied, lessonKey]);

  const handleMarkStudied = () => {
    if (!topic?.title || !lesson || !canMarkStudied || isStudied) return;

    markStudyGuideTopicStudied(topic.title, lesson);
    setIsStudied(true);
    trackChildActivityEvent("study_guide_completed", {
      topics: [topic.title],
      duration: secondsOnPage,
      metadata: {
        page: "Study Guide",
        topic: topic.title,
        lesson,
      },
    });
  };

  return (
    <main className="page-shell syllabus-page">
      <Header title="Study Lesson" onBack={onBack} onPrevious={onPrevious} onNext={onNext} />

      <section className="syllabus-intro study-lesson-intro">
        <div className="syllabus-icon" style={{ background: topic?.accent || "#5c257e" }}>
          <Icon size={36} />
        </div>
        <h1>{lesson || "Study Lesson"}</h1>
        <p>{topic?.title || "Study Guide"}</p>
      </section>

      {content ? (
        <SubtopicContent content={content} />
      ) : (
        <div className="empty-topic" style={{ margin: 0 }}>
          Study notes for <strong>{lesson}</strong> will be added soon.
        </div>
      )}

      <section className="premium-panel study-completion-card">
        <span className="result-eyebrow">Study Progress</span>
        <h2>{isStudied ? "Lesson marked as studied" : "Finish this lesson carefully"}</h2>
        <p>
          {isStudied
            ? "This lesson now counts toward Study Guide coverage in Success Track."
            : `Spend at least ${formatStudyTime(requiredStudySeconds - secondsOnPage)} more here, then mark it as studied.`}
        </p>
        <button
          className="primary-button"
          type="button"
          disabled={!canMarkStudied || isStudied}
          onClick={handleMarkStudied}
        >
          {isStudied ? "Studied" : "Mark Lesson as Studied"}
        </button>
      </section>
    </main>
  );
}

function formatStudyTime(seconds) {
  const safeSeconds = Math.max(0, seconds);
  const minutes = Math.floor(safeSeconds / 60);
  const remainingSeconds = safeSeconds % 60;

  if (minutes <= 0) return `${remainingSeconds} second${remainingSeconds === 1 ? "" : "s"}`;
  if (remainingSeconds === 0) return `${minutes} minute${minutes === 1 ? "" : "s"}`;

  return `${minutes} minute${minutes === 1 ? "" : "s"} ${remainingSeconds} second${remainingSeconds === 1 ? "" : "s"}`;
}

function isClassPracticeAnswerCorrect(typedAnswer, expectedAnswer) {
  const typed = normalizeAnswerText(typedAnswer);
  const expected = normalizeAnswerText(expectedAnswer);

  if (!typed) return false;

  if (
    expected.includes("any correct") ||
    expected.includes("learner's choice") ||
    expected.includes("completed") ||
    expected.includes("must be") ||
    expected.includes("answers depend") ||
    expected.includes("correct story")
  ) {
    return typed.length > 0;
  }

  return typed === expected;
}

function ClassPracticeTestsPage({ studentSession, week, onBack, onPrevious, onNext, onTutorHelp }) {
  const classInfo = getClassInfo(studentSession?.class_level);
  const allTopics = CLASS_PRACTICE_TESTS[classInfo.id] || [];
  const scopedWeekNumber = Number(week?.week || 0);
  const topics = scopedWeekNumber
    ? allTopics.filter((topicItem) => topicItem.week === scopedWeekNumber)
    : allTopics;
  const storageKey = `proTutorsHub_classPractice_${classInfo.id}`;
  const [openWeek, setOpenWeek] = useState(topics[0]?.week || null);
  const [practiceState, setPracticeState] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem(storageKey) || "{}");
    } catch {
      return {};
    }
  });

  useEffect(() => {
    localStorage.setItem(storageKey, JSON.stringify(practiceState));
  }, [practiceState, storageKey]);

  useEffect(() => {
    setOpenWeek(topics[0]?.week || null);
  }, [classInfo.id, scopedWeekNumber]);

  const responses = practiceState.responses || {};
  const submitted = practiceState.submitted || {};
  const revealed = practiceState.revealed || {};
  const totalQuestions = topics.reduce((sum, topicItem) => sum + topicItem.questions.length, 0);
  const submittedCount = Object.keys(submitted).filter((key) => submitted[key]).length;
  const correctCount = topics.reduce((sum, topicItem) => {
    return sum + topicItem.questions.filter((question) => {
      const key = `${topicItem.week}-${question.id}`;
      return submitted[key] && isClassPracticeAnswerCorrect(responses[key], question.answer);
    }).length;
  }, 0);

  const updateResponse = (key, value) => {
    setPracticeState((current) => ({
      ...current,
      responses: { ...(current.responses || {}), [key]: value },
      submitted: { ...(current.submitted || {}), [key]: false },
      revealed: { ...(current.revealed || {}), [key]: false },
    }));
  };

  const submitAnswer = (key) => {
    setPracticeState((current) => ({
      ...current,
      submitted: { ...(current.submitted || {}), [key]: true },
    }));
  };

  const revealAnswer = (key) => {
    setPracticeState((current) => ({
      ...current,
      revealed: { ...(current.revealed || {}), [key]: true },
    }));
  };

  if (!topics.length) {
    return (
      <main className="page-shell syllabus-page">
        <Header title="Practice Tests" onBack={onBack} onPrevious={onPrevious} onNext={onNext} />
        <section className="syllabus-intro">
          <h1>{classInfo.label} Practice Tests</h1>
          <p>Practice tests for this class will be added soon.</p>
        </section>
      </main>
    );
  }

  return (
    <main className="page-shell syllabus-page class-practice-page">
      <Header title="Practice Tests" onBack={onBack} onPrevious={onPrevious} onNext={onNext} />

      <section className="class-practice-hero">
        <div>
          <span className="result-eyebrow">{classInfo.label} Mathematics</span>
          <h1>{scopedWeekNumber ? `Week ${scopedWeekNumber} Practice Test` : "Topic-by-Topic Practice Tests"}</h1>
          <p>
            {scopedWeekNumber
              ? "This week has 20 practice questions. Type your answer first, then submit to check."
              : "Each topic has 20 practice questions. Type your answer first, then submit to check."}
          </p>
        </div>
        <div className="class-practice-score" aria-label="Practice progress">
          <strong>{correctCount}/{totalQuestions}</strong>
          <span>correct</span>
          <small>{submittedCount} submitted</small>
        </div>
      </section>

      <section className="class-practice-grid" aria-label={`${classInfo.label} practice topics`}>
        {topics.map((topicItem) => {
          const isOpen = openWeek === topicItem.week;
          const topicSubmitted = topicItem.questions.filter((question) => submitted[`${topicItem.week}-${question.id}`]).length;
          const topicCorrect = topicItem.questions.filter((question) => {
            const key = `${topicItem.week}-${question.id}`;
            return submitted[key] && isClassPracticeAnswerCorrect(responses[key], question.answer);
          }).length;

          return (
            <article className={`class-practice-topic-card ${isOpen ? "open" : ""}`} key={`${classInfo.id}-${topicItem.week}`}>
              <button type="button" onClick={() => setOpenWeek(isOpen ? null : topicItem.week)}>
                <span className="class-practice-week">Week {topicItem.week}</span>
                <span>
                  <b>{topicItem.title}</b>
                  <small>{topicItem.focus}</small>
                </span>
                <em>{topicCorrect}/{topicItem.questions.length}</em>
              </button>

              {isOpen && (
                <div className="class-practice-topic-detail">
                  <div className="class-practice-topic-head">
                    <h2>{topicItem.title}</h2>
                    <p>{topicSubmitted}/20 submitted. Answers appear only after submitting.</p>
                  </div>

                  <div className="class-practice-question-grid">
                    {topicItem.questions.map((question, index) => {
                      const key = `${topicItem.week}-${question.id}`;
                      const typed = responses[key] || "";
                      const hasSubmitted = Boolean(submitted[key]);
                      const isCorrect = hasSubmitted && isClassPracticeAnswerCorrect(typed, question.answer);
                      const showAnswer = Boolean(revealed[key]);

                      return (
                        <label className={`b3-answer-row class-practice-answer ${isCorrect ? "correct" : ""}`} key={key}>
                          <span>{index + 1}. {renderFractions(question.prompt)}</span>
                          {question.hint && <p>{question.hint}</p>}
                          <textarea
                            value={typed}
                            placeholder="Type your answer here"
                            onChange={(event) => updateResponse(key, event.target.value)}
                          />
                          <div className="b3-answer-actions">
                            <button type="button" onClick={() => submitAnswer(key)}>
                              Submit
                            </button>
                            {hasSubmitted && !isCorrect && (
                              <button className="secondary" type="button" onClick={() => revealAnswer(key)}>
                                Show Answer
                              </button>
                            )}
                          </div>
                          {hasSubmitted && (
                            <small className={isCorrect ? "right" : "wrong"}>
                              {isCorrect ? "Correct." : "Not yet. Check the method and try again."}
                            </small>
                          )}
                          {showAnswer && (
                            <small className="right">Answer: {renderFractions(question.answer)}</small>
                          )}
                        </label>
                      );
                    })}
                  </div>
                </div>
              )}
            </article>
          );
        })}
      </section>

      <NeedTutorCard onClick={onTutorHelp} />
    </main>
  );
}

