const getSchoolPasswordKey = (username) => `proTutorsHub_schoolStudentPassword:${normalizeStudentUsername(username)}`;
const getSchoolPasswordChangedKey = (username) => `proTutorsHub_schoolStudentPasswordChanged:${normalizeStudentUsername(username)}`;

function getStoredSchoolPassword(username, fallbackPassword) {
  if (typeof window === "undefined") return fallbackPassword;
  return window.localStorage.getItem(getSchoolPasswordKey(username)) || fallbackPassword;
}

function hasChangedDefaultSchoolPassword(username) {
  if (typeof window === "undefined") return false;
  return window.localStorage.getItem(getSchoolPasswordChangedKey(username)) === "true";
}

function saveSchoolPassword(username, password) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(getSchoolPasswordKey(username), password);
  window.localStorage.setItem(getSchoolPasswordChangedKey(username), "true");
}

function ForceSchoolPasswordChangePage({ studentSession, onPasswordChanged, onLogout }) {
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");

  const handleChangePassword = () => {
    setError("");
    if (password.length < 6) {
      setError("Please use at least 6 characters.");
      return;
    }
    if (password !== confirmPassword) {
      setError("Passwords do not match.");
      return;
    }
    if (password === "math123") {
      setError("Please choose a new password different from the default password.");
      return;
    }

    saveSchoolPassword(studentSession.username, password);
    onPasswordChanged({
      ...studentSession,
      mustChangePassword: false,
      password_changed: true,
    });
  };

  return (
    <main className="page-shell auth-page">
      <section className="auth-card premium-panel">
        <div className="brand auth-brand">
          <img src={APP_INFO.logo} alt="Pro Tutors Hub logo" className="brand-image" />
          <div>
            <span className="brand-subtitle">{studentSession?.school_name}</span>
            <strong className="brand-name">Change Password</strong>
          </div>
        </div>
        <span className="result-eyebrow">First login security</span>
        <h1>Create Your Own Password</h1>
        <p>{studentSession?.student_name}, your school account used a default password. Please change it before opening your dashboard.</p>
        <div className="auth-form-grid single">
          <PasswordInput label="New password" value={password} autoComplete="new-password" onChange={setPassword} />
          <PasswordInput label="Confirm new password" value={confirmPassword} autoComplete="new-password" onChange={setConfirmPassword} />
        </div>
        <button className="primary-button" onClick={handleChangePassword}>
          Save Password and Continue
        </button>
        <button className="secondary-button" onClick={onLogout}>
          Log out
        </button>
        {error && <div className="auth-message error">{error}</div>}
      </section>
    </main>
  );
}

function StudentAccountGate({ onAuthenticated }) {
  const [mode, setMode] = useState("school");
  const [form, setForm] = useState({
    studentFirstName: "",
    studentLastName: "",
    age: "",
    username: "",
    password: "",
    parentEmail: "",
    parentWhatsAppNumber: "",
  });
  const [recoveryUsername, setRecoveryUsername] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [usernameSuggestions, setUsernameSuggestions] = useState([]);
  const [busy, setBusy] = useState(false);
  const [schoolLogin, setSchoolLogin] = useState({
    school_id: demoSchools[0]?.school_id || "",
    class_level: "basic-1",
    username: "",
    password: "",
    term: "First Term",
  });

  const selectedSchool = demoSchools.find((school) => school.school_id === schoolLogin.school_id) || demoSchools[0];
  const schoolClassStudents = demoStudents.filter(
    (student) => student.school_id === selectedSchool?.school_id && student.class_level === schoolLogin.class_level
  );
  const selectedSchoolStudent = schoolClassStudents.find((student) => student.username === schoolLogin.username) || schoolClassStudents[0];

  const updateField = (field, value) => {
    setForm((current) => ({ ...current, [field]: value }));
  };

  const updateSchoolLogin = (field, value) => {
    setSchoolLogin((current) => {
      const next = { ...current, [field]: value };
      if (field === "school_id" || field === "class_level") {
        const nextSchool = demoSchools.find((school) => school.school_id === (field === "school_id" ? value : next.school_id)) || demoSchools[0];
        const nextStudents = demoStudents.filter(
          (student) => student.school_id === nextSchool?.school_id && student.class_level === (field === "class_level" ? value : next.class_level)
        );
        next.username = nextStudents[0]?.username || "";
      }
      return next;
    });
  };

  const runAction = async (action) => {
    setBusy(true);
    setError("");
    setMessage("");

    try {
      await action();
    } catch (actionError) {
      setError(actionError.message || "Something went wrong. Please try again.");
      setUsernameSuggestions(actionError.suggestions || []);
    } finally {
      setBusy(false);
    }
  };

  const handleSignup = () =>
    runAction(async () => {
      const result = await createStudentAccount(form);
      onAuthenticated(result.session);
      trackChildActivityEvent("logged_in", {
        metadata: { childName: getStudentDisplayName(result.session), source: "signup" },
      });
    });

  const handleLogin = () =>
    runAction(async () => {
      const result = await loginStudent(form);
      onAuthenticated(result.session);
      trackChildActivityEvent("logged_in", {
        metadata: { childName: getStudentDisplayName(result.session), source: "login" },
      });
    });

  const handleSchoolLogin = () =>
    runAction(async () => {
      const effectiveUsername = schoolLogin.username || selectedSchoolStudent?.username || "";
      const student = demoStudents.find(
        (item) =>
          item.school_id === schoolLogin.school_id &&
          item.class_level === schoolLogin.class_level &&
          item.username === effectiveUsername
      );

      if (!student) {
        throw new Error("Please select a valid school, class and student.");
      }

      const expectedPassword = getStoredSchoolPassword(student.username, student.password);
      if (schoolLogin.password !== expectedPassword) {
        throw new Error("Incorrect password for this student.");
      }

      const [firstName, ...lastParts] = student.student_name.split(" ");
      const session = {
        ...student,
        studentFirstName: firstName || student.student_name,
        studentLastName: lastParts.join(" "),
        parentEmail: "",
        accountType: "school",
        term: schoolLogin.term,
        mustChangePassword: !hasChangedDefaultSchoolPassword(student.username) && schoolLogin.password === student.password,
      };

      onAuthenticated(session);
      trackChildActivityEvent("logged_in", {
        metadata: {
          childName: student.student_name,
          source: "school-login",
          school: student.school_name,
          classLevel: student.class_level,
        },
      });
    });

  const handleRecovery = () =>
    runAction(async () => {
      const result = await requestParentPasswordReset(recoveryUsername);
      setMessage(result.parentEmail ? `${result.message} Check ${result.parentEmail}.` : result.message);
    });

  return (
    <main className="page-shell auth-page">
      <section className="auth-card premium-panel">
        <div className="brand auth-brand">
          <img src={APP_INFO.logo} alt="Pro Tutors Hub logo" className="brand-image" />
          <div>
            <span className="brand-subtitle">Pro Tutors Hub</span>
            <strong className="brand-name">Study Account</strong>
          </div>
        </div>

        {mode === "school" && (
          <>
            <span className="result-eyebrow">School access</span>
            <h1>Primary Mathematics Learning Platform</h1>
            <p>Select your school, class and student name. Usernames follow the school format, for example <strong>BFA-B5-001</strong>.</p>
            <div className="auth-form-grid">
              <label>
                Select School
                <select value={schoolLogin.school_id} onChange={(event) => updateSchoolLogin("school_id", event.target.value)}>
                  {demoSchools.map((school) => (
                    <option key={school.school_id} value={school.school_id}>{school.school_name}</option>
                  ))}
                </select>
              </label>
              <label>
                Select Class
                <select value={schoolLogin.class_level} onChange={(event) => updateSchoolLogin("class_level", event.target.value)}>
                  {CLASS_LEVELS.map((classInfo) => (
                    <option key={classInfo.id} value={classInfo.id}>{classInfo.label}</option>
                  ))}
                </select>
              </label>
              <label>
                Select Student Name
                <select value={schoolLogin.username || selectedSchoolStudent?.username || ""} onChange={(event) => updateSchoolLogin("username", event.target.value)}>
                  {schoolClassStudents.map((student) => (
                    <option key={student.username} value={student.username}>{student.student_name} - {student.username}</option>
                  ))}
                </select>
              </label>
              <label>
                Term
                <select value={schoolLogin.term} onChange={(event) => updateSchoolLogin("term", event.target.value)}>
                  {TERM_OPTIONS.map((term) => (
                    <option key={term} value={term}>{term}</option>
                  ))}
                </select>
              </label>
              <PasswordInput label="Enter Password" value={schoolLogin.password} onChange={(value) => updateSchoolLogin("password", value)} />
            </div>
            <div className="school-login-preview">
              <span>school_id: {selectedSchool?.school_id}</span>
              <span>school_code: {selectedSchool?.school_code}</span>
              <span>subscription_status: {selectedSchool?.subscription_status}</span>
            </div>
            <button className="primary-button" disabled={busy} onClick={handleSchoolLogin}>
              Login
            </button>
            <button className="secondary-button" onClick={() => setMode(hasKnownStudentAccount() ? "login" : "signup")}>
              Use personal account
            </button>
          </>
        )}

        {mode === "signup" && (
          <>
            <span className="result-eyebrow">First time here?</span>
            <h1>Create My Study Account</h1>
            <p>Set up a simple student account. Parent email is used for account recovery.</p>
            <div className="auth-form-grid">
              <label>
                Student first name
                <input value={form.studentFirstName} onChange={(event) => updateField("studentFirstName", event.target.value)} />
              </label>
              <label>
                Student last name
                <input value={form.studentLastName} onChange={(event) => updateField("studentLastName", event.target.value)} />
              </label>
              <label>
                Age
                <input type="number" min="3" max="20" value={form.age} onChange={(event) => updateField("age", event.target.value)} />
              </label>
              <label>
                Username
                <input value={form.username} onChange={(event) => updateField("username", event.target.value)} />
              </label>
              <PasswordInput label="Password" value={form.password} autoComplete="new-password" onChange={(value) => updateField("password", value)} />
              <label>
                Parent email for account recovery
                <input type="email" value={form.parentEmail} onChange={(event) => updateField("parentEmail", event.target.value)} />
              </label>
              <label>
                Parent WhatsApp number
                <input value={form.parentWhatsAppNumber} onChange={(event) => updateField("parentWhatsAppNumber", event.target.value)} />
              </label>
            </div>
            <button className="primary-button" disabled={busy} onClick={handleSignup}>
              Create My Study Account
            </button>
            {usernameSuggestions.length > 0 && (
              <div className="username-suggestion-panel">
                <strong>Try one of these usernames:</strong>
                <div className="chip-grid">
                  {usernameSuggestions.map((suggestion) => (
                    <button
                      key={suggestion}
                      onClick={() => {
                        updateField("username", normalizeStudentUsername(suggestion));
                        setUsernameSuggestions([]);
                        setError("");
                      }}
                    >
                      {suggestion}
                    </button>
                  ))}
                </div>
              </div>
            )}
            <button className="secondary-button" onClick={() => setMode("login")}>
              I already have an account
            </button>
            <button className="secondary-button" onClick={() => setMode("school")}>
              Back to school login
            </button>
          </>
        )}

        {mode === "login" && (
          <>
            <span className="result-eyebrow">Welcome back</span>
            <h1>Log In To Study</h1>
            <p>Stay signed in on this device after login.</p>
            <div className="auth-form-grid single">
              <label>
                Username
                <input value={form.username} onChange={(event) => updateField("username", event.target.value)} />
              </label>
              <PasswordInput label="Password" value={form.password} onChange={(value) => updateField("password", value)} />
            </div>
            <button className="primary-button" disabled={busy} onClick={handleLogin}>
              Login
            </button>
            <button className="secondary-button" onClick={() => setMode("recovery")}>
              Forgot Password?
            </button>
            <button className="secondary-button" onClick={() => setMode("signup")}>
              Create a new student account
            </button>
            <button className="secondary-button" onClick={() => setMode("school")}>
              Back to school login
            </button>
          </>
        )}

        {mode === "recovery" && (
          <>
            <span className="result-eyebrow">Parent help</span>
            <h1>Ask Parent to Reset Password</h1>
            <p>Enter the student username. We will send a secure one-time reset link to the linked parent email.</p>
            <div className="auth-form-grid single">
              <label>
                Student username
                <input value={recoveryUsername} onChange={(event) => setRecoveryUsername(event.target.value)} />
              </label>
            </div>
            <button className="primary-button" disabled={busy} onClick={handleRecovery}>
              Send To Parent Email
            </button>
            <button className="secondary-button" onClick={() => setMode("login")}>
              Back to login
            </button>
          </>
        )}

        {error && <div className="auth-message error">{error}</div>}
        {message && <div className="auth-message">{message}</div>}
      </section>
    </main>
  );
}

function ResetPasswordPage({ resetToken, onDone }) {
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const handleReset = async () => {
    setBusy(true);
    setError("");
    setMessage("");

    try {
      if (password !== confirmPassword) {
        throw new Error("Passwords do not match.");
      }
      const result = await completeParentPasswordReset(resetToken, password);
      setMessage(result.message || "Password reset successfully.");
      if (typeof window !== "undefined") {
        window.history.replaceState({}, "", window.location.pathname);
      }
    } catch (resetError) {
      setError(resetError.message || "Unable to reset password.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <main className="page-shell auth-page">
      <section className="auth-card premium-panel">
        <div className="brand auth-brand">
          <img src={APP_INFO.logo} alt="Pro Tutors Hub logo" className="brand-image" />
          <div>
            <span className="brand-subtitle">Pro Tutors Hub</span>
            <strong className="brand-name">Reset Password</strong>
          </div>
        </div>
        <span className="result-eyebrow">Secure parent reset</span>
        <h1>Create a New Password</h1>
        <p>This reset link can be used once and expires after 30 minutes.</p>
        <div className="auth-form-grid single">
          <PasswordInput label="New password" value={password} autoComplete="new-password" onChange={setPassword} />
          <PasswordInput label="Confirm new password" value={confirmPassword} autoComplete="new-password" onChange={setConfirmPassword} />
        </div>
        <button className="primary-button" disabled={busy || !resetToken} onClick={handleReset}>
          Reset Password
        </button>
        <button className="secondary-button" onClick={onDone}>
          Back to login
        </button>
        {error && <div className="auth-message error">{error}</div>}
        {message && <div className="auth-message">{message}</div>}
      </section>
    </main>
  );
}

